"""Compile original bilingual answers for the Owner's synthetic question corpus.

No network, user records or uploaded instructions are executed. Shared answers
are reused only for questions with the same practical response.
"""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]
RESPONSES={};ASSIGNMENTS={}
LESSONS={}


def lesson(topic,ids):
    for value in ids.split():
        prefix,numbers=value.split(':')
        for item in numbers.split(','):
            ends=item.split('-')
            for n in range(int(ends[0]),int(ends[-1])+1):
                key=f'{prefix}.{n:04d}'
                assert key not in ASSIGNMENTS and key not in LESSONS,key
                LESSONS[key]=topic


def language(key,ids,uz,en,examples):
    assert len(examples)==3
    uz+='\n\n🧩 3 ta misol:\n'+'\n'.join(f'{i}) {a}\n— {b}' for i,(a,b) in enumerate(examples,1))
    en+='\n\n🧩 Three examples:\n'+'\n'.join(f'{i}) {a}' for i,(a,b) in enumerate(examples,1))
    add(key,ids,uz,en)


def refine(ids):
    """Replace a broad shared answer with a more specific authored answer."""
    for identifier in ids:
        ASSIGNMENTS.pop(identifier,None);LESSONS.pop(identifier,None)


def add(key,ids,uz,en,kind='answer'):
    assert key not in RESPONSES,key
    RESPONSES[key]={'uz':uz,'en':en,'kind':kind}
    for value in ids.split():
        prefix,numbers=value.split(':')
        for item in numbers.split(','):
            ends=item.split('-');start=int(ends[0]);end=int(ends[-1])
            for n in range(start,end+1):
                identifier=f'{prefix}.{n:04d}'
                assert identifier not in ASSIGNMENTS,(identifier,key)
                ASSIGNMENTS[identifier]=key


