def compile_pack():
    corpus=json.loads((ROOT/'services/backend/contracts/riwi_question_corpus_v1.json').read_text())
    assert len(corpus['entries'])==1640
    assert not set(LESSONS)&set(ASSIGNMENTS)
    ids={e['id'] for e in corpus['entries']}
    assert set(LESSONS)|set(ASSIGNMENTS)==ids,ids-(set(LESSONS)|set(ASSIGNMENTS))
    for entry in corpus['entries']:
        if entry['id'] in LESSONS:entry['lessonId']=LESSONS[entry['id']]
        else:entry['responseId']=ASSIGNMENTS[entry['id']]
    corpus.update(version='riwi-question-answers-v1',responses=RESPONSES,
        provenance='Original assistant-authored bilingual explanations and conservative routing, based on Owner-supplied synthetic questions. No learner records, external AI or neural parameter training.',
        review={'mode':'authored_rules_and_examples','notALanguageModel':True,'factsReviewedAt':'2026-11-03',
          'currentPricesSchedulesAndPrivateRecords':'require_live_authorized_data'},
        references=[
          'https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-listening',
          'https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-reading',
          'https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-writing',
          'https://ielts.org/take-a-test/your-results/ielts-scoring-in-detail',
          'https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/404',
          'https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Status/500',
          'https://www.python.org/about/', 'https://www.postgresql.org/about/',
          'https://www.cdc.gov/sleep/about/', 'https://whc.unesco.org/en/statesparties/UZ',
          'https://www.ipcc.ch/report/ar6/syr/summary-for-policymakers/'])
    return corpus


if __name__=='__main__':
    pack=compile_pack()
    (ROOT/'services/backend/contracts/riwi_question_answers_v1.json').write_text(json.dumps(pack,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'questions':len(pack['entries']),'responseProfiles':len(RESPONSES),'lessonMappings':len(LESSONS),'decisions':{k:sum(e['decision']==k for e in pack['entries']) for k in ('answer','deny','conditional')}}))

